def read_query(workspace_id, database_id, sql, params=None, max_rows=None, **_extra):
    import json, os, datetime, time, re, sqlite3, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0386000" if __import__("os").path.isdir("./environment_mix/0386000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _rows(x):
        if isinstance(x, list):
            return x
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        return []

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        token = hashlib.sha1(f"{time.time_ns()}:{os.getpid()}:{os.urandom(16)}".encode("utf-8")).hexdigest().upper()
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        num = int(token[:24], 16)
        out = []
        for _ in range(24):
            num, r = divmod(num, 36)
            out.append(alphabet[r])
        return f"{prefix}_{''.join(out)}"

    def _strip_leading_comments_and_ws(s):
        i, L = 0, len(s)
        while i < L:
            ch = s[i]
            if ch.isspace():
                i += 1
                continue
            if ch == "-" and i + 1 < L and s[i + 1] == "-":
                j = s.find("\n", i + 2)
                if j == -1:
                    return ""
                i = j + 1
                continue
            if ch == "/" and i + 1 < L and s[i + 1] == "*":
                j = s.find("*/", i + 2)
                if j == -1:
                    return ""
                i = j + 2
                continue
            return s[i:]
        return ""

    def _count_qmarks(sql_text):
        # Count '?' that are not inside single/double quotes or comments.
        s = sql_text
        i, n = 0, len(s)
        count = 0
        in_sq = False
        in_dq = False
        in_line_comment = False
        in_block_comment = False
        while i < n:
            ch = s[i]
            nxt = s[i + 1] if i + 1 < n else ""
            if in_line_comment:
                if ch == "\n":
                    in_line_comment = False
                i += 1
                continue
            if in_block_comment:
                if ch == "*" and nxt == "/":
                    in_block_comment = False
                    i += 2
                else:
                    i += 1
                continue
            if not in_sq and not in_dq:
                if ch == "-" and nxt == "-":
                    in_line_comment = True
                    i += 2
                    continue
                if ch == "/" and nxt == "*":
                    in_block_comment = True
                    i += 2
                    continue
            if not in_dq and ch == "'" and not in_line_comment and not in_block_comment:
                # handle escaped '' inside single quotes
                if in_sq and nxt == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if not in_sq and ch == '"' and not in_line_comment and not in_block_comment:
                # handle escaped "" inside double quotes
                if in_dq and nxt == '"':
                    i += 2
                    continue
                in_dq = not in_dq
                i += 1
                continue
            if not in_sq and not in_dq and ch == "?":
                count += 1
            i += 1
        return count

    t0 = time.time()
    req_now = _now()

    def _log_request(api_key_id, status_s, error_code=None, execution_id=None):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        logs.append(
            {
                "id": _gen_id("req"),
                "endpoint": "read_query",
                "workspace_id": workspace_id,
                "database_id": database_id,
                "api_key_id": api_key_id,
                "execution_id": execution_id,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "created_at": req_now,
            }
        )
        _save("request_logs.json", logs)

    # ---- validate inputs (types/patterns only; do not over-reject) ----
    if not isinstance(workspace_id, str) or not re.match(r"^ws_[0-9A-Z]{18,}$", workspace_id):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must match ^ws_[0-9A-Z]{18,}$.")
    if not isinstance(database_id, str) or not re.match(r"^db_[0-9A-Z]{18,}$", database_id):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "database_id must match ^db_[0-9A-Z]{18,}$.")
    if not isinstance(sql, str) or len(sql) < 1 or not sql.strip():
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sql must be a non-empty string.")
    if params is None:
        params = []
    if not isinstance(params, list):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "params must be an array.")
    if max_rows is None:
        max_rows = 1000
    if not isinstance(max_rows, int) or max_rows < 1:
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "max_rows must be an integer >= 1.")

    # For read_query: require statement is SELECT/WITH/EXPLAIN (read-only).
    lead = _strip_leading_comments_and_ws(sql).lstrip().upper()
    if not (lead.startswith("SELECT") or lead.startswith("WITH") or lead.startswith("EXPLAIN")):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "read_query may execute only SELECT/WITH/EXPLAIN statements (business rule).")

    # Placeholder check should not fire if statement has 0 placeholders and params empty;
    # if params provided but no placeholders, real servers commonly reject.
    ph = _count_qmarks(sql)
    if ph != len(params):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err(
            "VALIDATION_ERROR",
            "params do not match the number of '?' placeholders.",
            placeholders=ph,
            params=len(params),
        )

    # ---- resolve auth context (ambient): pick an active api_key whose workspace is active and matches workspace_id ----
    workspaces = _rows(_load("workspaces.json"))
    api_keys = _rows(_load("api_keys.json"))
    dbs = _rows(_load("databases.json"))
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log_request(None, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log_request(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active; SQL tools are rejected (business rule).")

    key_row = next((k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not key_row:
        _log_request(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available for this workspace (business rule).")

    db = next((d for d in dbs if d.get("id") == database_id and d.get("workspace_id") == workspace_id), None)
    if not db:
        _log_request(key_row.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Database not found in workspace.")
    if db.get("status") in ("offline", "deleted"):
        _log_request(key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Database is offline or deleted; SQL tools are rejected (business rule).")

    # ---- create execution row and run ----
    executions = _rows(_load("sql_executions.json"))
    exec_id = _gen_id("exec")
    exec_row = {
        "id": exec_id,
        "workspace_id": workspace_id,
        "database_id": database_id,
        "api_key_id": key_row.get("id"),
        "tool_name": "read_query",
        "sql_text": sql,
        "status": "queued",
        "error_message": None,
        "rows_returned": None,
        "rows_affected": None,
        "duration_ms": None,
        "table_name_hint": None,
        "result_preview_json": None,
        "created_at": req_now,
        "updated_at": req_now,
    }
    executions.append(exec_row)
    _save("sql_executions.json", executions)

    # Transition to running
    run_now = _now()
    for r in executions:
        if r.get("id") == exec_id:
            r["status"] = "running"
            r["updated_at"] = run_now
            break
    _save("sql_executions.json", executions)

    # Apply caps
    cap = db.get("max_result_rows")
    if not isinstance(cap, int) or cap < 1:
        cap = 1000
    effective_limit = min(max_rows, cap)

    started = time.time()
    try:
        conn = sqlite3.connect(db.get("file_path"))
        try:
            pragma = db.get("pragma_settings") if isinstance(db.get("pragma_settings"), dict) else None
            if pragma:
                for k, v in pragma.items():
                    try:
                        conn.execute(f"PRAGMA {k}={v}")
                    except sqlite3.Error:
                        pass
            cur = conn.cursor()
            cur.execute(sql, params)
            cols = [d[0] for d in (cur.description or [])]
            rows = cur.fetchmany(effective_limit + 1)
            truncated = len(rows) > effective_limit
            if truncated:
                rows_out = rows[:effective_limit]
            else:
                rows_out = rows
            # Convert to JSON-serializable-ish values
            data_rows = []
            for tup in rows_out:
                if isinstance(tup, tuple):
                    data_rows.append(list(tup))
                else:
                    data_rows.append(tup)
            preview = None
            if truncated:
                preview = {"truncated": True, "returned": effective_limit, "fetched_plus_one": len(rows), "cap_applied": effective_limit}
            duration_ms = int(max(0, (time.time() - started) * 1000))
        finally:
            conn.close()
    except sqlite3.Error as e:
        duration_ms = int(max(0, (time.time() - started) * 1000))
        fail_now = _now()
        for r in executions:
            if r.get("id") == exec_id:
                r["status"] = "failed"
                r["error_message"] = f"SQL error: {str(e)}"
                r["duration_ms"] = duration_ms
                r["updated_at"] = fail_now
                break
        _save("sql_executions.json", executions)
        _log_request(key_row.get("id"), "error", "VALIDATION_ERROR", execution_id=exec_id)
        return _err("VALIDATION_ERROR", f"SQL error: {str(e)}", execution_id=exec_id)

    succ_now = _now()
    for r in executions:
        if r.get("id") == exec_id:
            r["status"] = "succeeded"
            r["rows_returned"] = len(data_rows)
            r["rows_affected"] = 0
            r["duration_ms"] = duration_ms
            r["result_preview_json"] = preview
            r["updated_at"] = succ_now
            break
    _save("sql_executions.json", executions)

    # update api key last_used_at
    for k in api_keys:
        if k.get("id") == key_row.get("id"):
            k["last_used_at"] = succ_now
            k["updated_at"] = succ_now
            break
    _save("api_keys.json", api_keys)

    _log_request(key_row.get("id"), "ok", None, execution_id=exec_id)
    return {
        "execution": next((r for r in executions if r.get("id") == exec_id), exec_row),
        "columns": cols,
        "rows": data_rows,
        "max_rows": max_rows,
        "effective_max_rows": effective_limit,
    }

def write_query(workspace_id, database_id, sql, params=None, **_extra):
    import json, os, datetime, time, re, sqlite3, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0386000" if __import__("os").path.isdir("./environment_mix/0386000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _rows(x):
        if isinstance(x, list):
            return x
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        return []

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        token = hashlib.sha1(f"{time.time_ns()}:{os.getpid()}:{os.urandom(16)}".encode("utf-8")).hexdigest().upper()
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        num = int(token[:24], 16)
        out = []
        for _ in range(24):
            num, r = divmod(num, 36)
            out.append(alphabet[r])
        return f"{prefix}_{''.join(out)}"

    def _strip_leading_comments_and_ws(s):
        i, L = 0, len(s)
        while i < L:
            ch = s[i]
            if ch.isspace():
                i += 1
                continue
            if ch == "-" and i + 1 < L and s[i + 1] == "-":
                j = s.find("\n", i + 2)
                if j == -1:
                    return ""
                i = j + 1
                continue
            if ch == "/" and i + 1 < L and s[i + 1] == "*":
                j = s.find("*/", i + 2)
                if j == -1:
                    return ""
                i = j + 2
                continue
            return s[i:]
        return ""

    def _count_qmarks(sql_text):
        s = sql_text
        i, n = 0, len(s)
        count = 0
        in_sq = False
        in_dq = False
        in_line_comment = False
        in_block_comment = False
        while i < n:
            ch = s[i]
            nxt = s[i + 1] if i + 1 < n else ""
            if in_line_comment:
                if ch == "\n":
                    in_line_comment = False
                i += 1
                continue
            if in_block_comment:
                if ch == "*" and nxt == "/":
                    in_block_comment = False
                    i += 2
                else:
                    i += 1
                continue
            if not in_sq and not in_dq:
                if ch == "-" and nxt == "-":
                    in_line_comment = True
                    i += 2
                    continue
                if ch == "/" and nxt == "*":
                    in_block_comment = True
                    i += 2
                    continue
            if not in_dq and ch == "'":
                if in_sq and nxt == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if not in_sq and ch == '"':
                if in_dq and nxt == '"':
                    i += 2
                    continue
                in_dq = not in_dq
                i += 1
                continue
            if not in_sq and not in_dq and ch == "?":
                count += 1
            i += 1
        return count

    t0 = time.time()
    req_now = _now()

    def _log_request(api_key_id, status_s, error_code=None, execution_id=None):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        logs.append(
            {
                "id": _gen_id("req"),
                "endpoint": "write_query",
                "workspace_id": workspace_id,
                "database_id": database_id,
                "api_key_id": api_key_id,
                "execution_id": execution_id,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "created_at": req_now,
            }
        )
        _save("request_logs.json", logs)

    # ---- validate inputs ----
    if not isinstance(workspace_id, str) or not re.match(r"^ws_[0-9A-Z]{18,}$", workspace_id):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must match ^ws_[0-9A-Z]{18,}$.")
    if not isinstance(database_id, str) or not re.match(r"^db_[0-9A-Z]{18,}$", database_id):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "database_id must match ^db_[0-9A-Z]{18,}$.")
    if not isinstance(sql, str) or len(sql) < 1 or not sql.strip():
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sql must be a non-empty string.")
    if params is None:
        params = []
    if not isinstance(params, list):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "params must be an array.")

    lead = _strip_leading_comments_and_ws(sql).lstrip().upper()
    # Allow optional transaction wrappers by allowing BEGIN/COMMIT/ROLLBACK preceding a single DML;
    # we keep it simple: reject obvious non-write heads.
    if lead.startswith(("SELECT", "WITH", "EXPLAIN", "CREATE", "DROP", "ALTER", "PRAGMA")):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "write_query may execute only INSERT/UPDATE/DELETE (business rule).")
    if not (lead.startswith("INSERT") or lead.startswith("UPDATE") or lead.startswith("DELETE") or lead.startswith("BEGIN") or lead.startswith("COMMIT") or lead.startswith("ROLLBACK")):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "write_query may execute only INSERT/UPDATE/DELETE (and transaction wrappers) (business rule).")

    ph = _count_qmarks(sql)
    if ph != len(params):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err(
            "VALIDATION_ERROR",
            "params do not match the number of '?' placeholders.",
            placeholders=ph,
            params=len(params),
        )

    # ---- resolve workspace, active key, db ----
    workspaces = _rows(_load("workspaces.json"))
    api_keys = _rows(_load("api_keys.json"))
    dbs = _rows(_load("databases.json"))

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log_request(None, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log_request(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active; SQL tools are rejected (business rule).")
    key_row = next((k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not key_row:
        _log_request(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available for this workspace (business rule).")

    db = next((d for d in dbs if d.get("id") == database_id and d.get("workspace_id") == workspace_id), None)
    if not db:
        _log_request(key_row.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Database not found in workspace.")
    if db.get("status") in ("offline", "deleted"):
        _log_request(key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Database is offline or deleted; SQL tools are rejected (business rule).")
    if db.get("status") == "read_only":
        _log_request(key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Database is read_only; write_query is rejected (business rule).")

    # ---- create execution row and run ----
    executions = _rows(_load("sql_executions.json"))
    exec_id = _gen_id("exec")
    exec_row = {
        "id": exec_id,
        "workspace_id": workspace_id,
        "database_id": database_id,
        "api_key_id": key_row.get("id"),
        "tool_name": "write_query",
        "sql_text": sql,
        "status": "queued",
        "error_message": None,
        "rows_returned": 0,
        "rows_affected": None,
        "duration_ms": None,
        "table_name_hint": None,
        "result_preview_json": None,
        "created_at": req_now,
        "updated_at": req_now,
    }
    executions.append(exec_row)
    _save("sql_executions.json", executions)

    run_now = _now()
    for r in executions:
        if r.get("id") == exec_id:
            r["status"] = "running"
            r["updated_at"] = run_now
            break
    _save("sql_executions.json", executions)

    started = time.time()
    try:
        conn = sqlite3.connect(db.get("file_path"))
        try:
            pragma = db.get("pragma_settings") if isinstance(db.get("pragma_settings"), dict) else None
            if pragma:
                for k, v in pragma.items():
                    try:
                        conn.execute(f"PRAGMA {k}={v}")
                    except sqlite3.Error:
                        pass
            cur = conn.cursor()
            cur.execute(sql, params)
            conn.commit()
            affected = cur.rowcount
            if affected is None or affected < 0:
                affected = 0
            duration_ms = int(max(0, (time.time() - started) * 1000))
        finally:
            conn.close()
    except sqlite3.Error as e:
        duration_ms = int(max(0, (time.time() - started) * 1000))
        fail_now = _now()
        for r in executions:
            if r.get("id") == exec_id:
                r["status"] = "failed"
                r["error_message"] = f"SQL error: {str(e)}"
                r["duration_ms"] = duration_ms
                r["updated_at"] = fail_now
                break
        _save("sql_executions.json", executions)
        _log_request(key_row.get("id"), "error", "VALIDATION_ERROR", execution_id=exec_id)
        return _err("VALIDATION_ERROR", f"SQL error: {str(e)}", execution_id=exec_id)

    succ_now = _now()
    for r in executions:
        if r.get("id") == exec_id:
            r["status"] = "succeeded"
            r["rows_affected"] = affected
            r["duration_ms"] = duration_ms
            r["updated_at"] = succ_now
            break
    _save("sql_executions.json", executions)

    for k in api_keys:
        if k.get("id") == key_row.get("id"):
            k["last_used_at"] = succ_now
            k["updated_at"] = succ_now
            break
    _save("api_keys.json", api_keys)

    _log_request(key_row.get("id"), "ok", None, execution_id=exec_id)
    return {"execution": next((r for r in executions if r.get("id") == exec_id), exec_row)}

def create_table(workspace_id, database_id, sql, **_extra):
