        out = []
        for _ in range(24):
            num, r = divmod(num, 36)
            out.append(alphabet[r])
        return f"{prefix}_{''.join(out)}"

    def _strip_leading_comments_and_ws(s):
        i, L = 0, len(s)
        while i < L:
            ch = s[i]
            if ch.isspace():
                i += 1
                continue
            if ch == "-" and i + 1 < L and s[i + 1] == "-":
                j = s.find("\n", i + 2)
                if j == -1:
                    return ""
                i = j + 1
                continue
            if ch == "/" and i + 1 < L and s[i + 1] == "*":
                j = s.find("*/", i + 2)
                if j == -1:
                    return ""
                i = j + 2
                continue
            return s[i:]
        return ""

    t0 = time.time()
    req_now = _now()

    def _log_request(api_key_id, status_s, error_code=None, execution_id=None):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        logs.append(
            {
                "id": _gen_id("req"),
                "endpoint": "create_table",
                "workspace_id": workspace_id,
                "database_id": database_id,
                "api_key_id": api_key_id,
                "execution_id": execution_id,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "created_at": req_now,
            }
        )
        _save("request_logs.json", logs)

    # ---- validate inputs ----
    if not isinstance(workspace_id, str) or not re.match(r"^ws_[0-9A-Z]{18,}$", workspace_id):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must match ^ws_[0-9A-Z]{18,}$.")
    if not isinstance(database_id, str) or not re.match(r"^db_[0-9A-Z]{18,}$", database_id):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "database_id must match ^db_[0-9A-Z]{18,}$.")
    if not isinstance(sql, str) or len(sql) < 1 or not sql.strip():
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sql must be a non-empty string.")

    lead = _strip_leading_comments_and_ws(sql).lstrip().upper()
    # Business rule: only CREATE TABLE (and optionally CREATE INDEX); no DROP/ALTER.
    if not lead.startswith("CREATE"):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "create_table may execute only CREATE TABLE (and optionally CREATE INDEX) (business rule).")
    if (" DROP " in f" {lead} ") or lead.startswith("DROP") or (" ALTER " in f" {lead} ") or lead.startswith("ALTER"):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "DROP/ALTER is rejected for create_table (business rule).")
    if not (lead.startswith("CREATE TABLE") or lead.startswith("CREATE INDEX") or lead.startswith("CREATE UNIQUE INDEX")):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "create_table accepts CREATE TABLE (and optionally CREATE INDEX) statements only (business rule).")

    # ---- resolve workspace, active key, db ----
    workspaces = _rows(_load("workspaces.json"))
    api_keys = _rows(_load("api_keys.json"))
    dbs = _rows(_load("databases.json"))

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log_request(None, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log_request(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active; SQL tools are rejected (business rule).")

    key_row = next((k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not key_row:
        _log_request(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available for this workspace (business rule).")

    db = next((d for d in dbs if d.get("id") == database_id and d.get("workspace_id") == workspace_id), None)
    if not db:
        _log_request(key_row.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Database not found in workspace.")
    if db.get("status") in ("offline", "deleted"):
        _log_request(key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Database is offline or deleted; SQL tools are rejected (business rule).")
    if db.get("status") == "read_only":
        _log_request(key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Database is read_only; create_table is rejected (business rule).")

    # ---- create execution and run ----
    executions = _rows(_load("sql_executions.json"))
    exec_id = _gen_id("exec")
    exec_row = {
        "id": exec_id,
        "workspace_id": workspace_id,
        "database_id": database_id,
        "api_key_id": key_row.get("id"),
        "tool_name": "create_table",
        "sql_text": sql,
        "status": "queued",
        "error_message": None,
        "rows_returned": 0,
        "rows_affected": None,
        "duration_ms": None,
        "table_name_hint": None,
        "result_preview_json": None,
        "created_at": req_now,
        "updated_at": req_now,
    }
    executions.append(exec_row)
    _save("sql_executions.json", executions)

    run_now = _now()
    for r in executions:
        if r.get("id") == exec_id:
            r["status"] = "running"
            r["updated_at"] = run_now
            break
    _save("sql_executions.json", executions)

    started = time.time()
    created_table_name = None
    try:
        # best-effort extract table name for hint
        m = re.match(r"(?is)^\s*CREATE\s+TABLE\s+(IF\s+NOT\s+EXISTS\s+)?([`\"\[]?)([A-Za-z_][A-Za-z0-9_\.]*)\2", sql.strip())
        if m:
            created_table_name = m.group(3).split(".")[-1]

        conn = sqlite3.connect(db.get("file_path"))
        try:
            pragma = db.get("pragma_settings") if isinstance(db.get("pragma_settings"), dict) else None
            if pragma:
                for k, v in pragma.items():
                    try:
                        conn.execute(f"PRAGMA {k}={v}")
                    except sqlite3.Error:
                        pass
            cur = conn.cursor()
            cur.execute(sql)
            conn.commit()
            affected = cur.rowcount
            if affected is None or affected < 0:
                affected = 0
            duration_ms = int(max(0, (time.time() - started) * 1000))
        finally:
            conn.close()
    except sqlite3.Error as e:
        duration_ms = int(max(0, (time.time() - started) * 1000))
        fail_now = _now()
        for r in executions:
            if r.get("id") == exec_id:
                r["status"] = "failed"
                r["error_message"] = f"SQL error: {str(e)}"
                r["duration_ms"] = duration_ms
                r["table_name_hint"] = created_table_name
                r["updated_at"] = fail_now
                break
        _save("sql_executions.json", executions)
        _log_request(key_row.get("id"), "error", "VALIDATION_ERROR", execution_id=exec_id)
        return _err("VALIDATION_ERROR", f"SQL error: {str(e)}", execution_id=exec_id)

    succ_now = _now()
    for r in executions:
        if r.get("id") == exec_id:
            r["status"] = "succeeded"
            r["rows_affected"] = affected
            r["duration_ms"] = duration_ms
            r["table_name_hint"] = created_table_name
            r["updated_at"] = succ_now
            break
    _save("sql_executions.json", executions)

    # Refresh db_tables catalog entry for created table (best-effort)
    if created_table_name:
        db_tables = _rows(_load("db_tables.json"))
        existing = next((t for t in db_tables if t.get("database_id") == database_id and t.get("name") == created_table_name), None)
        if existing:
            if existing.get("status") != "present":
                existing["status"] = "present"
            existing["type"] = existing.get("type") or "table"
            existing["last_refreshed_at"] = succ_now
            existing["updated_at"] = succ_now
        else:
            db_tables.append(
                {
                    "id": _gen_id("tbl"),
                    "database_id": database_id,
                    "name": created_table_name,
                    "type": "table",
                    "status": "present",
                    "create_sql": None,
                    "schema_json": None,
                    "last_refreshed_at": succ_now,
                    "created_at": succ_now,
                    "updated_at": succ_now,
                }
            )
        _save("db_tables.json", db_tables)

    for k in api_keys:
        if k.get("id") == key_row.get("id"):
            k["last_used_at"] = succ_now
            k["updated_at"] = succ_now
            break
    _save("api_keys.json", api_keys)

    _log_request(key_row.get("id"), "ok", None, execution_id=exec_id)
    return {"execution": next((r for r in executions if r.get("id") == exec_id), exec_row)}

def list_tables(workspace_id, database_id, type=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, sqlite3, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0386000" if __import__("os").path.isdir("./environment_mix/0386000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        token = hashlib.sha1(f"{time.time_ns()}:{os.getpid()}:{os.urandom(16)}".encode("utf-8")).hexdigest().upper()
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        num = int(token[:24], 16)
        out = []
        for _ in range(24):
            num, r = divmod(num, 36)
            out.append(alphabet[r])
        return f"{prefix}_{''.join(out)}"

    def _get_rows(x):
        if isinstance(x, list):
            return x
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        return []

    def _encode_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or cur == "":
            raise ValueError("cursor")
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        data = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
        obj = json.loads(data.decode("utf-8"))
        off = obj.get("offset")
        if not isinstance(off, int) or off < 0:
            raise ValueError("cursor")
        return off

    def _log_request(api_key_id, status_s, error_code=None, execution_id=None):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        logs.append({
            "id": _gen_id("req"),
            "endpoint": "list_tables",
            "workspace_id": workspace_id,
            "database_id": database_id,
            "api_key_id": api_key_id,
            "execution_id": execution_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _resolve_auth_workspace():
        keys = _get_rows(_load("api_keys.json"))
        wss = {w.get("id"): w for w in _get_rows(_load("workspaces.json")) if isinstance(w, dict)}
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            ws = wss.get(k.get("workspace_id"))
            if not ws or ws.get("status") != "active":
                continue
            return k, ws
        return None, None

    # ---- validate ----
    if not isinstance(workspace_id, str) or not re.match(r"^ws_[0-9A-Z]{18,}$", workspace_id):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(database_id, str) or not re.match(r"^db_[0-9A-Z]{18,}$", database_id):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid database_id.")
    if type is not None and type not in ("table", "view"):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid type.")
    if status is not None and status not in ("present", "dropped"):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
    if sort is None:
        sort = "name"
    if sort not in ("name", "created_at", "updated_at", "last_refreshed_at"):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort.")
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order.")
    try:
        offset = _decode_cursor(cursor)
    except Exception:
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    # ---- auth ambient ----
    api_key_row, authed_ws = _resolve_auth_workspace()
    if not api_key_row or not authed_ws:
        _log_request(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key/workspace context available.")

    # ---- find ws/db ----
    ws_rows = _get_rows(_load("workspaces.json"))
    ws = next((w for w in ws_rows if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log_request(api_key_row.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log_request(api_key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active for SQL tools.", workspace_status=ws.get("status"))

    db_rows = _get_rows(_load("databases.json"))
    db = next((d for d in db_rows if isinstance(d, dict) and d.get("id") == database_id and d.get("workspace_id") == workspace_id), None)
    if not db:
        _log_request(api_key_row.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Database not found in workspace.")
    if db.get("status") in ("offline", "deleted"):
        _log_request(api_key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Database is not available for SQL tools.", database_status=db.get("status"))

    # ---- refresh db_tables from sqlite_master (business rule) ----
    file_path = db.get("file_path")
    if isinstance(file_path, str) and file_path:
        try:
            conn = sqlite3.connect(file_path)
            try:
                rows = conn.execute(
                    "SELECT name, type, sql FROM sqlite_master WHERE type IN ('table','view') AND name NOT LIKE 'sqlite_%' ORDER BY name"
                ).fetchall()
                dbt = _get_rows(_load("db_tables.json"))
                now2 = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                idx = {}
                for i, r in enumerate(dbt):
                    if isinstance(r, dict):
                        idx[(r.get("database_id"), r.get("name"))] = i
                present = set()
                for nm, tp, create_sql in rows:
                    present.add(nm)
                    key = (database_id, nm)
                    if key in idx:
                        i = idx[key]
                        row = dbt[i]
                        row["type"] = "view" if tp == "view" else "table"
                        row["status"] = "present"
                        row["create_sql"] = create_sql
                        row["last_refreshed_at"] = now2
                        row["updated_at"] = now2
                        dbt[i] = row
                    else:
                        dbt.append({
                            "id": _gen_id("tbl"),
                            "database_id": database_id,
                            "name": nm,
                            "type": "view" if tp == "view" else "table",
                            "status": "present",
                            "create_sql": create_sql,
                            "schema_json": None,
                            "last_refreshed_at": now2,
                            "created_at": now2,
                            "updated_at": now2
                        })
                for i, r in enumerate(dbt):
                    if not isinstance(r, dict):
                        continue
                    if r.get("database_id") != database_id:
                        continue
                    if r.get("status") == "present" and r.get("name") not in present:
                        r["status"] = "dropped"
                        r["updated_at"] = now2
                        dbt[i] = r
                _save("db_tables.json", dbt)
            finally:
                try:
                    conn.close()
                except Exception:
                    pass
        except sqlite3.Error:
            pass

    # ---- query catalog ----
    dbt = [r for r in _get_rows(_load("db_tables.json")) if isinstance(r, dict) and r.get("database_id") == database_id]
    if type is not None:
        dbt = [r for r in dbt if r.get("type") == type]
    if status is not None:
        dbt = [r for r in dbt if r.get("status") == status]

    reverse = (order == "desc")
    def _sort_key(r):
        v = r.get(sort)
        return (v is None, v)
    dbt.sort(key=_sort_key, reverse=reverse)

    total = len(dbt)
    page = dbt[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    _log_request(api_key_row.get("id"), "ok")
    return {
        "data": page,
        "metadata": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

