        "result_preview_json": None,
        "created_at": req_now,
        "updated_at": req_now,
    }
    executions.append(exec_row)
    _save("sql_executions.json", executions)

    run_now = _now()
    for r in executions:
        if r.get("id") == exec_id:
            r["status"] = "running"
            r["updated_at"] = run_now
            break
    _save("sql_executions.json", executions)

    started = time.time()
    # refresh db_tables from sqlite_master and then verify existence
    try:
        conn = sqlite3.connect(db.get("file_path"))
        try:
            cur = conn.cursor()
            cur.execute("SELECT name, type, sql FROM sqlite_master WHERE type IN ('table','view')")
            master = cur.fetchall()
        finally:
            conn.close()
    except sqlite3.Error as e:
        duration_ms = int(max(0, (time.time() - started) * 1000))
        fail_now = _now()
        for r in executions:
            if r.get("id") == exec_id:
                r["status"] = "failed"
                r["error_message"] = f"SQL error: {str(e)}"
                r["duration_ms"] = duration_ms
                r["updated_at"] = fail_now
                break
        _save("sql_executions.json", executions)
        _log_request(key_row.get("id"), "error", "VALIDATION_ERROR", execution_id=exec_id)
        return _err("VALIDATION_ERROR", f"SQL error: {str(e)}", execution_id=exec_id)

    # Update db_tables catalog
    db_tables = _rows(_load("db_tables.json"))
    seen = {}
    for name, typ, create_sql in master:
        if name is None:
            continue
        # exclude internal sqlite_ tables by default
        if isinstance(name, str) and name.lower().startswith("sqlite_"):
            continue
        if typ not in ("table", "view"):
            continue
        seen[name] = (typ, create_sql)

    now2 = _now()
    # mark present/dropped for this database
    for t in db_tables:
        if t.get("database_id") != database_id:
            continue
        n = t.get("name")
        if n in seen:
            typ, create_sql = seen[n]
            if t.get("status") != "present":
                t["status"] = "present"
            t["type"] = typ
            t["create_sql"] = create_sql
            t["last_refreshed_at"] = now2
            t["updated_at"] = now2
        else:
            # only mark dropped if it was previously present (preserve dropped terminal)
            if t.get("status") == "present":
                t["status"] = "dropped"
                t["last_refreshed_at"] = now2
                t["updated_at"] = now2

    existing_names = {(t.get("database_id"), t.get("name")) for t in db_tables}
    for n, (typ, create_sql) in seen.items():
        if (database_id, n) not in existing_names:
            db_tables.append(
                {
                    "id": _gen_id("tbl"),
                    "database_id": database_id,
                    "name": n,
                    "type": typ,
                    "status": "present",
                    "create_sql": create_sql,
                    "schema_json": None,
                    "last_refreshed_at": now2,
                    "created_at": now2,
                    "updated_at": now2,
                }
            )
    _save("db_tables.json", db_tables)

    present_row = next((t for t in db_tables if t.get("database_id") == database_id and t.get("name") == table_name and t.get("status") == "present"), None)
    if not present_row:
        duration_ms = int(max(0, (time.time() - started) * 1000))
        fail_now = _now()
        for r in executions:
            if r.get("id") == exec_id:
                r["status"] = "failed"
                r["error_message"] = f"table not found: {table_name} (refresh db tables and try again)"
                r["duration_ms"] = duration_ms
                r["updated_at"] = fail_now
                break
        _save("sql_executions.json", executions)
        _log_request(key_row.get("id"), "error", "NOT_FOUND", execution_id=exec_id)
        return _err("NOT_FOUND", f"Table/view not found: {table_name}", execution_id=exec_id)

    # Fetch PRAGMA table_info and indexes
    try:
        conn = sqlite3.connect(db.get("file_path"))
        try:
            cur = conn.cursor()
            cur.execute(f"PRAGMA table_info({table_name})")
            cols = cur.fetchall()
            cur.execute(f"PRAGMA index_list({table_name})")
            idxs = cur.fetchall()
            indexes = []
            for idx in idxs:
                # index_list: seq, name, unique, origin, partial (varies by SQLite version)
                idx_name = idx[1] if len(idx) > 1 else None
                if not idx_name:
                    continue
                cur.execute(f"PRAGMA index_info({idx_name})")
                idx_cols = cur.fetchall()
                indexes.append(
                    {
                        "name": idx_name,
                        "unique": bool(idx[2]) if len(idx) > 2 else None,
                        "columns": [c[2] for c in idx_cols if len(c) > 2],
                    }
                )
        finally:
            conn.close()
    except sqlite3.Error as e:
        duration_ms = int(max(0, (time.time() - started) * 1000))
        fail_now = _now()
        for r in executions:
            if r.get("id") == exec_id:
                r["status"] = "failed"
                r["error_message"] = f"SQL error: {str(e)}"
                r["duration_ms"] = duration_ms
                r["updated_at"] = fail_now
                break
        _save("sql_executions.json", executions)
        _log_request(key_row.get("id"), "error", "VALIDATION_ERROR", execution_id=exec_id)
        return _err("VALIDATION_ERROR", f"SQL error: {str(e)}", execution_id=exec_id)

    schema = {
        "name": table_name,
        "type": present_row.get("type"),
        "columns": [
            {
                "cid": c[0],
                "name": c[1],
                "type": c[2],
                "notnull": bool(c[3]),
                "default_value": c[4],
                "pk": bool(c[5]),
            }
            for c in cols
        ],
        "indexes": indexes,
        "create_sql": present_row.get("create_sql"),
    }

    succ_now = _now()
    duration_ms = int(max(0, (time.time() - started) * 1000))
    for t in db_tables:
        if t.get("id") == present_row.get("id"):
            t["schema_json"] = schema
            t["last_refreshed_at"] = succ_now
            t["updated_at"] = succ_now
            break
    _save("db_tables.json", db_tables)

    for r in executions:
        if r.get("id") == exec_id:
            r["status"] = "succeeded"
            r["rows_returned"] = len(schema.get("columns") or [])
            r["duration_ms"] = duration_ms
            r["result_preview_json"] = {"table": table_name, "type": present_row.get("type")}
            r["updated_at"] = succ_now
            break
    _save("sql_executions.json", executions)

    for k in api_keys:
        if k.get("id") == key_row.get("id"):
            k["last_used_at"] = succ_now
            k["updated_at"] = succ_now
            break
    _save("api_keys.json", api_keys)

    _log_request(key_row.get("id"), "ok", None, execution_id=exec_id)
    return {"execution": next((r for r in executions if r.get("id") == exec_id), exec_row), "schema": schema}

def append_insight(workspace_id, database_id, insight_text, source_execution_id=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0386000" if __import__("os").path.isdir("./environment_mix/0386000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "append_insight"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(status, api_key_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                logs.append({
                    "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{len(logs)+1}",
                    "endpoint": endpoint,
                    "status": status,
                    "error_code": error_code,
                    "api_key_id": api_key_id,
                    "workspace_id": workspace_id,
                    "database_id": database_id,
                    "latency_ms": latency_ms,
                    "created_at": _now()
                })
                _save(fname, logs)
                break

    # validation
    try:
        if not isinstance(workspace_id, str) or not re.match(r"^ws_[0-9A-Z]{18,}$", workspace_id):
            _log_call("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid workspace_id.")
        if not isinstance(database_id, str) or not re.match(r"^db_[0-9A-Z]{18,}$", database_id):
            _log_call("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid database_id.")
        if not isinstance(insight_text, str) or len(insight_text.strip()) < 1:
            _log_call("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "insight_text must be non-empty.")
        if source_execution_id is not None:
            if not isinstance(source_execution_id, str) or not re.match(r"^exec_[0-9A-Z]{18,}$", source_execution_id):
                _log_call("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid source_execution_id.")
    except Exception:
        _log_call("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid parameters.")

    workspaces = _load("workspaces.json")
    databases = _load("databases.json")
    api_keys = _load("api_keys.json")
    sql_execs = _load("sql_executions.json")
    insights = _load("insights.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log_call("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log_call("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active.")

    db = next((d for d in databases if isinstance(d, dict) and d.get("id") == database_id and d.get("workspace_id") == workspace_id), None)
    if not db:
        _log_call("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Database not found in workspace.")

    # source_execution check
    if source_execution_id is not None:
        ex = next((e for e in sql_execs if isinstance(e, dict) and e.get("id") == source_execution_id), None)
        if not ex:
            _log_call("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "source_execution_id not found.")
        # must belong to same workspace; database may differ but is typically same; enforce workspace.
        if ex.get("workspace_id") != workspace_id:
            _log_call("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "source_execution_id not accessible in this workspace.")

    # ambient auth: require some active key in workspace
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"]
    if not active_keys:
        _log_call("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available for workspace.")
    api_key_row = next((k for k in active_keys if isinstance(k.get("scopes"), list) and len(k.get("scopes")) >= 1), active_keys[0])

    # update key usage
    now = _now()
    for k in api_keys:
        if k.get("id") == api_key_row.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    # create insight (append-only)
    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}{hashlib.sha1(os.urandom(16)).hexdigest()[:18].upper()}"

    ins_id = _gen_id("ins")
    row = {
        "id": ins_id,
        "workspace_id": workspace_id,
        "database_id": database_id,
        "status": "active",
        "insight_text": insight_text,
        "source_execution_id": source_execution_id,
        "created_at": now,
        "updated_at": now
    }
    insights.append(row)
    _save("insights.json", insights)
    _log_call("ok", api_key_id=api_key_row.get("id"))
    return {"insight": row}

def get_current_identity(api_key, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0386000" if __import__("os").path.isdir("./environment_mix/0386000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_current_identity"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(status, api_key_id=None, workspace_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                logs.append({
                    "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{len(logs)+1}",
                    "endpoint": endpoint,
                    "status": status,
                    "error_code": error_code,
                    "api_key_id": api_key_id,
                    "workspace_id": workspace_id,
                    "latency_ms": latency_ms,
                    "created_at": _now()
                })
                _save(fname, logs)
                break

    # validation
    if not isinstance(api_key, str) or len(api_key) < 8:
        _log_call("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8.")

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")

    # authenticate by matching client-visible value or id; store has only key_hash, so accept api_key as id if matches.
    key_row = next((k for k in api_keys if isinstance(k, dict) and (k.get("id") == api_key)), None)
    if not key_row:
        _log_call("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key could not be verified.")

    if key_row.get("status") != "active":
        _log_call("error", api_key_id=key_row.get("id"), workspace_id=key_row.get("workspace_id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is revoked.")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == key_row.get("workspace_id")), None)
    if not ws:
        _log_call("error", api_key_id=key_row.get("id"), workspace_id=key_row.get("workspace_id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") == "deleted":
        _log_call("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is deleted.")

    # update last_used_at
    now = _now()
    for k in api_keys:
        if k.get("id") == key_row.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            key_row = k
            break
    _save("api_keys.json", api_keys)

    _log_call("ok", api_key_id=key_row.get("id"), workspace_id=ws.get("id"))

    # Quota/rate-limit consumption: if a request log collection exists, report rolling counts; otherwise zero.
    consumption = {"rate_limit": None, "quota": None}
    for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
        path = os.path.join(_DB, fname)
        if os.path.exists(path):
            logs = _load(fname)
            if isinstance(logs, list):
                now_dt = datetime.datetime.utcnow()
                one_min_ago = (now_dt - datetime.timedelta(minutes=1)).replace(microsecond=0).isoformat() + "Z"
                one_day_ago = (now_dt - datetime.timedelta(days=1)).replace(microsecond=0).isoformat() + "Z"
                per_min = sum(1 for r in logs if isinstance(r, dict) and r.get("api_key_id") == key_row.get("id") and (r.get("created_at") or "") >= one_min_ago)
                per_day = sum(1 for r in logs if isinstance(r, dict) and r.get("api_key_id") == key_row.get("id") and (r.get("created_at") or "") >= one_day_ago)
                consumption = {
                    "rate_limit": {"window": "1m", "requests": per_min},
                    "quota": {"window": "24h", "requests": per_day}
                }
            break

    return {
        "api_key": {
            "id": key_row.get("id"),
            "name": key_row.get("name"),
            "status": key_row.get("status"),
            "scopes": key_row.get("scopes"),
            "last_used_at": key_row.get("last_used_at"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at")
        },
        "workspace": ws,
        "consumption": consumption
    }

def create_database(api_key, workspace_id, name, file_path=None, pragma_settings=None, max_result_rows=None, **_extra):
    import json, os, datetime, time, re, sqlite3, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0386000" if __import__("os").path.isdir("./environment_mix/0386000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        token = hashlib.sha1(f"{time.time_ns()}:{os.getpid()}:{os.urandom(16)}".encode("utf-8")).hexdigest().upper()
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        num = int(token[:24], 16)
        out = []
        for _ in range(24):
            num, r = divmod(num, 36)
            out.append(alphabet[r])
        return f"{prefix}_{''.join(out)}"

    def _log_request(api_key_id, status_s, error_code=None):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        logs.append({
            "id": _gen_id("req"),
            "endpoint": "create_database",
            "workspace_id": workspace_id,
            "database_id": None,
            "api_key_id": api_key_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)

    # ---- validate ----
    if not isinstance(api_key, str) or len(api_key) < 8:
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8.")
    if not isinstance(workspace_id, str) or not re.match(r"^ws_[0-9A-Z]{18,}$", workspace_id):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(name, str) or len(name) < 1 or len(name) > 128:
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be 1..128 characters.")
    if file_path is not None and (not isinstance(file_path, str) or len(file_path) < 1):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "file_path must be a non-empty string when provided.")
    if pragma_settings is not None and not isinstance(pragma_settings, dict):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "pragma_settings must be an object when provided.")
    if max_result_rows is not None and (not isinstance(max_result_rows, int) or max_result_rows < 1 or max_result_rows > 100000):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "max_result_rows must be between 1 and 100000 when provided.")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    databases = _load("databases.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log_request(None, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log_request(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active.")

    # Authenticate api_key parameter by matching against client-visible value or id (never key_hash).
    # Store contains ids like key_...; accept exact id match, else treat as unresolvable (no plaintext available).
    key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key), None)
    if not key:
        _log_request(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid api_key.")
    if key.get("status") != "active":
        _log_request(key.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is revoked.")
    if key.get("workspace_id") != workspace_id:
        _log_request(key.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key not authorized for this workspace.")

    # uniqueness: db name unique per workspace
    for d in databases if isinstance(databases, list) else []:
        if isinstance(d, dict) and d.get("workspace_id") == workspace_id and d.get("name") == name and d.get("status") != "deleted":
            _log_request(key.get("id"), "error", "CONFLICT")
            return _err("CONFLICT", "A database with this name already exists in the workspace.")

    # determine file_path (server allocates if omitted)
    if file_path is None:
        # allocate under /app/database/sqlite/<workspace>/<db>.db (offline-safe)
        safe = re.sub(r"[^A-Za-z0-9._-]+", "_", name).strip("_") or "database"
        base_dir = os.path.join(_DB, "sqlite", workspace_id)
        try:
            os.makedirs(base_dir, exist_ok=True)
        except Exception:
            _log_request(key.get("id"), "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Server cannot allocate storage path for database.")
        file_path = os.path.join(base_dir, f"{safe}.db")

    # create sqlite file if possible (best-effort)
    try:
        if isinstance(file_path, str) and file_path.startswith("file:"):
            conn = sqlite3.connect(file_path, uri=True)
        else:
            parent = os.path.dirname(file_path)
            if parent:
                try:
                    os.makedirs(parent, exist_ok=True)
                except Exception:
                    pass
            conn = sqlite3.connect(file_path)
        conn.execute("PRAGMA user_version=1")
        conn.commit()
        conn.close()
    except sqlite3.Error:
        # allow record creation even if sqlite file cannot be initialized; managed systems may create later
        pass

    db_id = _gen_id("db")
    row = {
        "id": db_id,
        "workspace_id": workspace_id,
        "name": name,
        "status": "online",
        "file_path": file_path,
        "pragma_settings": pragma_settings if pragma_settings is not None else None,
        "max_result_rows": int(max_result_rows) if max_result_rows is not None else 10000,
        "created_at": now,
        "updated_at": now
    }
    if not isinstance(databases, list):
        databases = []
    databases.append(row)
    _save("databases.json", databases)

    # set default_database_id if empty
    if ws.get("default_database_id") in (None, ""):
        for i, w in enumerate(workspaces if isinstance(workspaces, list) else []):
            if isinstance(w, dict) and w.get("id") == workspace_id:
                w["default_database_id"] = db_id
                w["updated_at"] = now
                workspaces[i] = w
                _save("workspaces.json", workspaces)
                break

    # update key last_used_at
    if isinstance(api_keys, list):
        for i, k in enumerate(api_keys):
            if isinstance(k, dict) and k.get("id") == key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                api_keys[i] = k
                _save("api_keys.json", api_keys)
                break

    _log_request(key.get("id"), "ok", None)
    return {"database": row}

def list_databases(api_key, workspace_id, status=None, name_prefix=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0386000" if __import__("os").path.isdir("./environment_mix/0386000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- helpers
    def _log(status_code, api_key_id=None, workspace=None, extra=None):
        # best-effort request log in sql_executions as audit proxy for *every* call
        # tool_name enum does not include this endpoint; store under list_tables to satisfy enum constraint,
        # and set result_preview_json.endpoint to the real endpoint name.
        executions = _load("sql_executions.json")
        ws_id = workspace["id"] if isinstance(workspace, dict) and workspace.get("id") else workspace_id
        db_id = None
        if isinstance(workspace, dict):
            db_id = workspace.get("default_database_id")
        # choose any database in this workspace to satisfy FK constraint, else omit logging if none exist
        dbs = _load("databases.json")
        if not db_id:
            for d in dbs:
                if d.get("workspace_id") == ws_id:
                    db_id = d.get("id")
                    break
        if not db_id:
            return  # cannot satisfy required FK database_id
        eid = "sqlex_" + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")
        row = {
            "id": eid,
            "workspace_id": ws_id,
            "database_id": db_id,
            "api_key_id": api_key_id,
            "tool_name": "list_tables",
            "sql_text": None,
            "status": "succeeded" if status_code == "succeeded" else "failed",
            "error_message": None if status_code == "succeeded" else (extra or {}).get("error_message"),
            "rows_returned": None,
            "rows_affected": None,
            "duration_ms": int((time.time() - t0) * 1000),
            "table_name_hint": None,
            "result_preview_json": {"endpoint": "list_databases", "status": status_code, **(extra or {})},
            "created_at": now,
            "updated_at": now
        }
        executions.append(row)
        _save("sql_executions.json", executions)

    def _parse_cursor(cur):
        if not cur:
            return 0
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"==")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None
            off = obj.get("offset")
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _make_cursor(offset):
        obj = {"v": 1, "offset": offset}
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # --- input validation
    if not isinstance(api_key, str) or len(api_key) < 8:
        _log("failed", extra={"error_message": "Invalid api_key."})
        return _err("VALIDATION_ERROR", "Invalid api_key.")
    if not isinstance(workspace_id, str) or not re.match(r"^ws_[0-9A-Z]{18,}$", workspace_id):
        _log("failed", extra={"error_message": "Invalid workspace_id."})
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if status is not None:
        if not isinstance(status, str) or status not in ("online", "read_only", "offline", "deleted"):
            _log("failed", extra={"error_message": "Invalid status filter."})
            return _err("VALIDATION_ERROR", "Invalid status filter.")
    if name_prefix is not None:
        if not isinstance(name_prefix, str) or len(name_prefix) < 1:
            _log("failed", extra={"error_message": "Invalid name_prefix."})
            return _err("VALIDATION_ERROR", "Invalid name_prefix.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("failed", extra={"error_message": "Invalid limit."})
        return _err("VALIDATION_ERROR", "Invalid limit.")
    if sort is None:
        sort = "name"
    if sort not in ("name", "created_at", "updated_at"):
        _log("failed", extra={"error_message": "Invalid sort."})
        return _err("VALIDATION_ERROR", "Invalid sort.")
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log("failed", extra={"error_message": "Invalid order."})
        return _err("VALIDATION_ERROR", "Invalid order.")
    if cursor is not None and not isinstance(cursor, str):
        _log("failed", extra={"error_message": "Invalid cursor."})
        return _err("VALIDATION_ERROR", "Invalid cursor.")
    offset = _parse_cursor(cursor)
    if offset is None:
        _log("failed", extra={"error_message": "Invalid cursor."})
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    # --- auth + scope
    keys = _load("api_keys.json")
    key_row = None
    for k in keys:
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break
    if not key_row:
        _log("failed", extra={"error_message": "API key not found."})
        return _err("UNAUTHORIZED", "UNAUTHENTICATED: API key missing/invalid.")
    if key_row.get("status") != "active":
        _log("failed", api_key_id=key_row.get("id"), extra={"error_message": "API key revoked."})
        return _err("UNAUTHORIZED", "FORBIDDEN: API key revoked.")
    scopes = key_row.get("scopes") or []
    if not isinstance(scopes, list) or len(scopes) < 1:
        _log("failed", api_key_id=key_row.get("id"), extra={"error_message": "API key has no scopes."})
        return _err("UNAUTHORIZED", "FORBIDDEN: scopes do not permit this operation.")
    # minimal scope check: require any scope containing "db" or "database" or "*" or "admin"
    sjoin = " ".join([str(s) for s in scopes]).lower()
    if not (("*" in sjoin) or ("admin" in sjoin) or ("db" in sjoin) or ("database" in sjoin) or ("read" in sjoin) or ("list" in sjoin)):
        _log("failed", api_key_id=key_row.get("id"), extra={"error_message": "Insufficient scopes."})
        return _err("UNAUTHORIZED", "FORBIDDEN: scopes do not permit listing.")

    # workspace access: must own workspace via key
    if key_row.get("workspace_id") != workspace_id:
        _log("failed", api_key_id=key_row.get("id"), extra={"error_message": "Workspace not accessible."})
        return _err("NOT_FOUND", "workspace_id does not exist or is not accessible.")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log("failed", api_key_id=key_row.get("id"), extra={"error_message": "Workspace not found."})
        return _err("NOT_FOUND", "workspace_id does not exist or is not accessible.")

    # update key last_used_at
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    for i, k in enumerate(keys):
        if k.get("id") == key_row.get("id"):
            keys[i] = key_row
            break
    _save("api_keys.json", keys)

    # --- query
    dbs = _load("databases.json")
    rows = [d for d in dbs if d.get("workspace_id") == workspace_id]
    if status is not None:
        rows = [d for d in rows if d.get("status") == status]
    if name_prefix is not None:
        rows = [d for d in rows if isinstance(d.get("name"), str) and d["name"].startswith(name_prefix)]

    def _sort_key(d):
        v = d.get(sort)
        return ("" if v is None else v)

    rev = (order == "desc")
    rows.sort(key=_sort_key, reverse=rev)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    _log("succeeded", api_key_id=key_row.get("id"), workspace=ws, extra={"total": total, "returned": len(page)})

    return {
        "databases": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def update_database(api_key, workspace_id, database_id, name=None, pragma_settings=None, max_result_rows=None, status=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0386000" if __import__("os").path.isdir("./environment_mix/0386000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_rows(x):
        if isinstance(x, list):
            return x
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        return []

    def _gen_id(prefix):
        token = hashlib.sha1(f"{time.time_ns()}:{os.getpid()}:{os.urandom(16)}".encode("utf-8")).hexdigest().upper()
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        num = int(token[:24], 16)
        out = []
        for _ in range(24):
            num, r = divmod(num, 36)
            out.append(alphabet[r])
        return f"{prefix}_{''.join(out)}"

    def _log_request(api_key_id, status_s, error_code=None):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        logs.append({
            "id": _gen_id("req"),
            "endpoint": "update_database",
            "workspace_id": workspace_id,
            "database_id": database_id,
            "api_key_id": api_key_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)

    # ---- validate ----
    if not isinstance(api_key, str) or len(api_key) < 8:
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8.")
    if not isinstance(workspace_id, str) or not re.match(r"^ws_[0-9A-Z]{18,}$", workspace_id):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(database_id, str) or not re.match(r"^db_[0-9A-Z]{18,}$", database_id):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid database_id.")
    if name is not None:
        if not isinstance(name, str) or not (1 <= len(name) <= 128):
            _log_request(None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name must be a non-empty string up to 128 chars.")
    if pragma_settings is not None:
        if not isinstance(pragma_settings, dict):
            _log_request(None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "pragma_settings must be an object.")
        for k, v in pragma_settings.items():
            if not isinstance(k, str) or not k:
                _log_request(None, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "pragma_settings keys must be non-empty strings.")
            if not (v is None or isinstance(v, (str, int, float, bool))):
                _log_request(None, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "pragma_settings values must be string/number/boolean/null.")
    if max_result_rows is not None:
        if not isinstance(max_result_rows, int) or not (1 <= max_result_rows <= 100000):
            _log_request(None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "max_result_rows must be an integer between 1 and 100000.")
    if status is not None:
        if status not in ("online", "read_only", "offline", "deleted"):
            _log_request(None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.")

    # ---- authenticate api_key parameter against id OR client-visible value ----
    api_keys = _get_rows(_load("api_keys.json"))
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key:
            key_row = k
            break
    if key_row is None:
        # Also allow matching by a stored plaintext field if present (some stores include it)
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("key") == api_key or k.get("token") == api_key or k.get("value") == api_key:
                key_row = k
                break
    if key_row is None:
        _log_request(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")

    if key_row.get("status") != "active":
        _log_request(key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is revoked.")

    if key_row.get("workspace_id") != workspace_id:
        _log_request(key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key not authorized for this workspace.")

    workspaces = {w.get("id"): w for w in _get_rows(_load("workspaces.json")) if isinstance(w, dict)}
    ws = workspaces.get(workspace_id)
    if not ws:
        _log_request(key_row.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") == "deleted":
        _log_request(key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is deleted.")

    # ---- locate database ----
    db_rows = _get_rows(_load("databases.json"))
    db = None
    for d in db_rows:
        if isinstance(d, dict) and d.get("id") == database_id and d.get("workspace_id") == workspace_id:
            db = d
            break
    if not db:
        _log_request(key_row.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Database not found in workspace.")

    # ---- enforce uniqueness for name within workspace ----
    if name is not None and name != db.get("name"):
        for d in db_rows:
            if isinstance(d, dict) and d.get("workspace_id") == workspace_id and d.get("name") == name and d.get("id") != database_id:
                _log_request(key_row.get("id"), "error", "CONFLICT")
                return _err("CONFLICT", "Database name must be unique within the workspace.", field="name")

    # ---- enforce lifecycle transitions ----
    if status is not None:
        cur = db.get("status")
        transitions = {
            "online": ["read_only", "offline", "deleted"],
            "read_only": ["online", "offline", "deleted"],
            "offline": ["online", "deleted"],
            "deleted": []
        }
        if cur not in transitions or status not in transitions[cur]:
            _log_request(key_row.get("id"), "error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}.", from_status=cur, to_status=status)

    # ---- apply updates ----
    changed = False
    if name is not None and name != db.get("name"):
        db["name"] = name
        changed = True
    if pragma_settings is not None:
        db["pragma_settings"] = pragma_settings
        changed = True
    if max_result_rows is not None and max_result_rows != db.get("max_result_rows"):
        db["max_result_rows"] = max_result_rows
        changed = True
    if status is not None and status != db.get("status"):
        db["status"] = status
        changed = True

    if not changed:
        # no-op update is allowed; still should be observable via updated_at like real APIs often do
        db["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("databases.json", db_rows)
        key_row["last_used_at"] = db["updated_at"]
        key_row["updated_at"] = db["updated_at"]
        _save("api_keys.json", api_keys)
        _log_request(key_row.get("id"), "ok", None)
        return {"database": db}

    db["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("databases.json", db_rows)

    key_row["last_used_at"] = db["updated_at"]
    key_row["updated_at"] = db["updated_at"]
    _save("api_keys.json", api_keys)

    _log_request(key_row.get("id"), "ok", None)
    return {"database": db}

def list_sql_executions(api_key, workspace_id, database_id=None, status=None, tool_name=None, created_after=None, created_before=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0386000" if __import__("os").path.isdir("./environment_mix/0386000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "bad"
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc)
        except Exception:
            return "bad"

    def _parse_cursor(cur):
        if not cur:
            return 0
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"==")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None
            off = obj.get("offset")
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _make_cursor(offset):
        obj = {"v": 1, "offset": offset}
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _log(status_code, api_key_id=None, ws=None, db_id=None, err=None, extra=None):
        executions = _load("sql_executions.json")
        ws_id = (ws or {}).get("id") if isinstance(ws, dict) else workspace_id
        if not db_id:
            db_id = database_id
        # pick any db in workspace to satisfy FK
        dbs = _load("databases.json")
        if not db_id or not any(d.get("id") == db_id for d in dbs):
            fallback = next((d for d in dbs if d.get("workspace_id") == ws_id), None)
            if not fallback:
                return
            db_id = fallback.get("id")
        eid = "sqlex_" + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")
        row = {
            "id": eid,
            "workspace_id": ws_id,
            "database_id": db_id,
            "api_key_id": api_key_id,
            "tool_name": "list_tables",
            "sql_text": None,
            "status": "succeeded" if status_code == "succeeded" else "failed",
            "error_message": None if status_code == "succeeded" else err,
            "rows_returned": None,
            "rows_affected": None,
            "duration_ms": int((time.time() - t0) * 1000),
            "table_name_hint": None,
            "result_preview_json": {"endpoint": "list_sql_executions", "status": status_code, **(extra or {})},
            "created_at": now,
            "updated_at": now
        }
        executions.append(row)
        _save("sql_executions.json", executions)

    # --- validation
    if not isinstance(api_key, str) or len(api_key) < 8:
        _log("failed", err="Invalid api_key.")
        return _err("VALIDATION_ERROR", "Invalid api_key.")
    if not isinstance(workspace_id, str) or not re.match(r"^ws_[0-9A-Z]{18,}$", workspace_id):
        _log("failed", err="Invalid workspace_id.")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if database_id is not None:
        if not isinstance(database_id, str) or not re.match(r"^db_[0-9A-Z]{18,}$", database_id):
            _log("failed", err="Invalid database_id.")
            return _err("VALIDATION_ERROR", "Invalid database_id.")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        _log("failed", err="Invalid status.")
        return _err("VALIDATION_ERROR", "Invalid status.")
    # schema enum does not include append_insight, but tool parameter does; allow filter but it will match none.
    if tool_name is not None and tool_name not in ("read_query", "write_query", "create_table", "list_tables", "describe_table", "append_insight"):
        _log("failed", err="Invalid tool_name.")
        return _err("VALIDATION_ERROR", "Invalid tool_name.")
    da = _parse_dt(created_after)
    db = _parse_dt(created_before)
    if da == "bad":
        _log("failed", err="Invalid created_after.")
        return _err("VALIDATION_ERROR", "Invalid created_after.")
    if db == "bad":
        _log("failed", err="Invalid created_before.")
        return _err("VALIDATION_ERROR", "Invalid created_before.")
    if da and db and not (da < db):
        _log("failed", err="created_after must be before created_before.")
        return _err("VALIDATION_ERROR", "created_after must be before created_before.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("failed", err="Invalid limit.")
        return _err("VALIDATION_ERROR", "Invalid limit.")
    if cursor is not None and not isinstance(cursor, str):
        _log("failed", err="Invalid cursor.")
        return _err("VALIDATION_ERROR", "Invalid cursor.")
    offset = _parse_cursor(cursor)
    if offset is None:
        _log("failed", err="Invalid cursor.")
        return _err("VALIDATION_ERROR", "Invalid cursor.")
    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "duration_ms"):
        _log("failed", err="Invalid sort.")
        return _err("VALIDATION_ERROR", "Invalid sort.")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _log("failed", err="Invalid order.")
        return _err("VALIDATION_ERROR", "Invalid order.")

    # --- auth
    keys = _load("api_keys.json")
    key_row = None
    for k in keys:
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break
    if not key_row:
        _log("failed", err="API key not found.")
        return _err("UNAUTHORIZED", "UNAUTHENTICATED: API key missing/invalid.")
    if key_row.get("status") != "active":
        _log("failed", api_key_id=key_row.get("id"), err="API key revoked.")
        return _err("UNAUTHORIZED", "FORBIDDEN: API key revoked.")
    scopes = key_row.get("scopes") or []
    sjoin = " ".join([str(s) for s in scopes]).lower()
    if not (("*" in sjoin) or ("admin" in sjoin) or ("audit" in sjoin) or ("log" in sjoin) or ("read" in sjoin) or ("sql" in sjoin)):
        _log("failed", api_key_id=key_row.get("id"), err="Insufficient scopes.")
        return _err("UNAUTHORIZED", "FORBIDDEN: scopes do not permit listing executions.")
    if key_row.get("workspace_id") != workspace_id:
        _log("failed", api_key_id=key_row.get("id"), err="Workspace not accessible.")
        return _err("NOT_FOUND", "workspace_id does not exist or is not accessible.")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log("failed", api_key_id=key_row.get("id"), err="Workspace not found.")
        return _err("NOT_FOUND", "workspace_id does not exist or is not accessible.")

    if database_id is not None:
        dbs = _load("databases.json")
        drow = next((d for d in dbs if d.get("id") == database_id and d.get("workspace_id") == workspace_id), None)
        if not drow:
            _log("failed", api_key_id=key_row.get("id"), ws=ws, db_id=None, err="Database not found.")
            return _err("NOT_FOUND", "database_id does not exist or is not accessible.")

    # update key last_used_at
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    for i, k in enumerate(keys):
        if k.get("id") == key_row.get("id"):
            keys[i] = key_row
            break
    _save("api_keys.json", keys)

    # --- query
    executions = _load("sql_executions.json")
    rows = [e for e in executions if e.get("workspace_id") == workspace_id]

    if database_id is not None:
        rows = [e for e in rows if e.get("database_id") == database_id]
    if status is not None:
        rows = [e for e in rows if e.get("status") == status]
    if tool_name is not None:
        # map append_insight: not stored in tool_name enum; attempt to match via result_preview_json.endpoint if present
        if tool_name == "append_insight":
            def _is_append_insight(e):
                rp = e.get("result_preview_json")
                return isinstance(rp, dict) and rp.get("endpoint") == "append_insight"
            rows = [e for e in rows if _is_append_insight(e)]
        else:
            rows = [e for e in rows if e.get("tool_name") == tool_name]

    if da is not None:
        rows2 = []
        for e in rows:
            ts = e.get("created_at")
            dt = _parse_dt(ts)
            if isinstance(dt, datetime.datetime) and dt >= da:
                rows2.append(e)
        rows = rows2
    if db is not None:
        rows2 = []
        for e in rows:
            ts = e.get("created_at")
            dt = _parse_dt(ts)
            if isinstance(dt, datetime.datetime) and dt < db:
                rows2.append(e)
        rows = rows2

    def _sort_key(e):
        v = e.get(sort)
        if sort in ("created_at", "updated_at"):
            return "" if v is None else v
        if sort == "duration_ms":
            return -1 if v is None else v
        return v

    rev = (order == "desc")
    rows.sort(key=_sort_key, reverse=rev)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    _log("succeeded", api_key_id=key_row.get("id"), ws=ws, db_id=database_id, extra={"total": total, "returned": len(page)})

    return {
        "executions": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def cancel_sql_execution(api_key, workspace_id, execution_id, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0386000" if __import__("os").path.isdir("./environment_mix/0386000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _rows(x):
        if isinstance(x, list):
            return x
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        return []

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        token = hashlib.sha1(f"{time.time_ns()}:{os.getpid()}:{os.urandom(16)}".encode("utf-8")).hexdigest().upper()
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        num = int(token[:24], 16)
        out = []
        for _ in range(24):
            num, r = divmod(num, 36)
            out.append(alphabet[r])
        return f"{prefix}_{''.join(out)}"

    t0 = time.time()
    req_now = _now()

    def _log_request(api_key_id, status_s, error_code=None):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        logs.append(
            {
                "id": _gen_id("req"),
                "endpoint": "cancel_sql_execution",
                "workspace_id": workspace_id,
                "database_id": None,
                "api_key_id": api_key_id,
                "execution_id": execution_id,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "created_at": req_now,
            }
        )
        _save("request_logs.json", logs)

    # ---- validate ----
    if not isinstance(api_key, str) or len(api_key) < 8:
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string of length >= 8.")
    if not isinstance(workspace_id, str) or not re.match(r"^ws_[0-9A-Z]{18,}$", workspace_id):
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must match ^ws_[0-9A-Z]{18,}$.")
    # IMPORTANT: do NOT over-validate execution_id beyond being a non-empty string.
    # The tool schema says ^sqlex_... but the datastore uses exec_...; accept both.
    if not isinstance(execution_id, str) or not execution_id.strip():
        _log_request(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "execution_id must be a non-empty string.")

    # ---- authenticate by api_key id or client-visible value (no hash comparison possible) ----
    api_keys = _rows(_load("api_keys.json"))
    key_row = None
    for k in api_keys:
        if k.get("id") == api_key:
            key_row = k
            break
    if not key_row:
        # No plaintext token exists in datastore; only id matching works here.
        _log_request(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")

    if key_row.get("status") != "active":
        _log_request(key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is revoked (business rule).")

    # ---- verify workspace ----
    workspaces = _rows(_load("workspaces.json"))
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log_request(key_row.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.")
    if key_row.get("workspace_id") != workspace_id:
        _log_request(key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key does not belong to this workspace.")

    # ---- find execution ----
    executions = _rows(_load("sql_executions.json"))
    ex = next((e for e in executions if e.get("id") == execution_id and e.get("workspace_id") == workspace_id), None)
    if not ex:
        _log_request(key_row.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Execution not found in workspace.")

    if ex.get("status") in ("succeeded", "failed", "cancelled"):
        _log_request(key_row.get("id"), "error", "CONFLICT")
        return _err("CONFLICT", "Execution is already in a terminal state and cannot be cancelled.", status=ex.get("status"))

    if ex.get("status") not in ("queued", "running"):
        _log_request(key_row.get("id"), "error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Execution cannot transition to cancelled from its current state.", status=ex.get("status"))

    # Transition to cancelled
    now2 = _now()
    for e in executions:
        if e.get("id") == execution_id:
            e["status"] = "cancelled"
            if not e.get("error_message"):
                e["error_message"] = "request cancelled by client"
            e["updated_at"] = now2
            break
    _save("sql_executions.json", executions)

    # update api key last_used_at
    for k in api_keys:
        if k.get("id") == key_row.get("id"):
            k["last_used_at"] = now2
            k["updated_at"] = now2
            break
    _save("api_keys.json", api_keys)

    _log_request(key_row.get("id"), "ok", None)
    return {"execution": next((e for e in executions if e.get("id") == execution_id), ex)}
